const response = $input.first().json;
let rawContent = '';

try {
  rawContent = response.choices[0].message.content;
} catch (e) {
  rawContent = '{}';
}

let blueprint = {};
try {
  blueprint = JSON.parse(rawContent);
} catch (e) {
  blueprint = { subtasks: [] };
}

const state = $node['Initialize State1'].json;
const currentRetry = ($json.retry_count || 0) + 1;
const deadlineDate = new Date(state.deadline);
const errors = [];
const subtasks = blueprint.subtasks || [];

// 1. Completeness Check
if (subtasks.length < 3) {
  errors.push('Decomposition is too brief. Need at least 3 distinct subtasks.');
}
subtasks.forEach((t, i) => {
  if (!t.title) {
    errors.push(`Task #${i+1} is missing title.`);
  }
});

// 2. Circular Dependency Check
const visited = new Set();
const recStack = new Set();
const adjMap = {};
subtasks.forEach(t => adjMap[t.task_id || t.title] = t.dependencies || []);

function hasCycle(node) {
  if (!visited.has(node)) {
    visited.add(node);
    recStack.add(node);
    const neighbors = adjMap[node] || [];
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor) && hasCycle(neighbor)) return true;
      else if (recStack.has(neighbor)) return true;
    }
  }
  recStack.delete(node);
  return false;
}

for (const t of subtasks) {
  const key = t.task_id || t.title;
  if (hasCycle(key)) {
    errors.push(`Circular dependency detected in task: ${key}`);
    break;
  }
}

const isValid = errors.length === 0;

return {
  assignment_id: state.assignment_id,
  course_id: state.course_id,
  course_name: state.course_name,
  project_name: state.project_name,
  goal_description: state.goal_description,
  deadline: state.deadline,
  alternate_link: state.alternate_link,
  team_members: state.team_members,
  blueprint: blueprint,
  is_valid: isValid,
  retry_count: currentRetry,
  error_logs: errors,
  manual_review_required: !isValid && currentRetry >= 3
};

const state = $input.first().json;
const subtasks = state.blueprint.subtasks || [];

return subtasks.map((t, idx) => {
  return {
    json: {
      id: `${state.assignment_id}_${idx + 1}`,
      assignment_id: state.assignment_id,
      task_order: idx + 1,
      task_title: t.title || t.task_title || `งานย่อยที่ ${idx + 1}`,
      description: `ผู้รับผิดชอบ: ${t.assignee || 'Student'} | ความเกี่ยวโยง: ${(t.dependencies || []).join(', ') || '-'}`,
      priority: (t.priority || 'MEDIUM').toUpperCase(),
      estimated_hours: Number(t.estimated_hours || 1),
      suggested_start_date: '',
      suggested_due_date: state.deadline,
      status: 'TODO'
    }
  };
});

